var particles=[];
var amount=800;
var noiseScale=0.005;
var c1,c2;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(212, 103, 8);
	noStroke();
	fill(255);
	for (let i=0;i<amount;i++){
		let pos =createVector(random(width),random(height));
		particles.push(pos);
	}
