	// 	}
}

function draw() {
	for(let i=0;i<particles.length;i++){
		let p=particles[i];
		circle(p.x,p.y,1);
		let n= noise(p.x*noiseScale,p.y*noiseScale,frameCount/noiseScale);
		let a= 2*PI*n;
		p.x+=sin(a*random(1,1.2));
		p.y+=cos(a)*map(sin(a/10),-1,1,-0.5,0.5);
		//p.y+=cos(a)*0.2
		if (!onScreen(p)) {
			p.x = random(width);
			p.y = random(height);
		}
	}
}

function onScreen(p) {
return p.x < width && p.y < height && p.x > 0 && p.y > 0
}
